on conflict (fdc_id, nutrient_id) do nothing;

-- Foods linked to canonical ingredients. A branded product is a FOOD of its canonical ingredient, never a new ingredient.
-- is_default becomes true only when the (ingredient, form) pair has no default yet.
insert into ingredient_foods (ingredient_id, form, fdc_id, is_default)
select i.id, v.form, v.fdc_id,
  (v.is_default and not exists (select 1 from ingredient_foods f where f.ingredient_id = i.id and f.form = v.form and f.is_default))
